use crate::income::IncomeSource;
use crate::money::Minor;

/// A source's smallest and largest receipt, scaled to a month the same way `typical` was.
pub(crate) fn monthly_range(s: &IncomeSource) -> (Minor, Minor) {
    if s.typical.minor == 0 {
        return (0, 0);
    }
    let per_month = s.monthly_equivalent.minor as f64 / s.typical.minor as f64;
    ((s.low.minor as f64 * per_month).round() as Minor, (s.high.minor as f64 * per_month).round() as Minor)
}
